def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self.__dict__.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index[key]
    except KeyError:
        raise IndexError(f"Key '{key}' not found in index")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())

    result = []
    for key in keys:
        if isinstance(key, int):
            if 0 <= key < len(self):
                result.append(self[key])
        elif isinstance(key, str):
            if key in self:
                result.append(self[key])
        else:
            raise ValueError(f"Invalid key type: {type(key)}")

    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        for key, value in self.items():
            result[key] = value
    else:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self):
                    raise IndexError("Index out of bounds")
                result[self.keys()[key]] = self.values()[key]
            elif isinstance(key, str):
                if key not in self:
                    result[key] = None
                else:
                    result[key] = self[key]
            else:
                raise TypeError("Invalid key type")
    return result

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to even (also known as "bankers' rounding").

    :param n: The number to round
    :return: The rounded number
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n >= 0:
        return int(n + 0.5 - 0.5 * (n + 0.5) % 1)
    else:
        return int(n - 0.5 + 0.5 * (n - 0.5) % 1)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    class Point:
        def __init__(self, *args, **kwargs):
            for field in fields:
                setattr(self, field, kwargs.get(field, None))

        def __repr__(self):
            return f"{self.__class__.__name__}({', '.join(f'{field}={getattr(self, field)}' for field in fields)})"

    Point.__name__ = name

    for field in fields:
        Point.__annotations__[field] = type(fields[field])

    Point.SRID_MAP = srid_map

    return Point

