def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                result = cache.get(key(*args, **kwargs))
                if result is None:
                    result = func(*args, **kwargs)
                    cache[key(*args, **kwargs)] = result
            finally:
                if lock is not None:
                    lock.release()
            return result
        return wrapper
    return decorator

import time

from functools import wraps

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class _TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = {}
            self.ttl = ttl
            self.timer = timer
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(kwargs.items())) if self.typed else (args, frozenset(kwargs.items()))
                if key in self.cache:
                    if self.timer() - self.cache[key][1] < self.ttl:
                        return self.cache[key][0]
                    else:
                        del self.cache[key]
                if len(self.cache) >= self.maxsize:
                    oldest_key = min(self.cache, key=lambda k: self.cache[k][1])
                    del self.cache[oldest_key]
                result = func(*args, **kwargs)
                self.cache[key] = (result, self.timer())
                return result
            return wrapper

    return _TTLCache(maxsize, ttl, timer, typed)

