def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                cache_key = key(func, self, *args, **kwargs)
                if cache_key not in cache:
                    cache[cache_key] = func(self, *args, **kwargs)
                return cache[cache_key]
            finally:
                if lock is not None:
                    lock.release()
        return wrapper
    return decorator

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a set to keep track of the minimal bases
    minimal = set()

    # Iterate over the classes in reverse order
    for cls in reversed(classes):
        # Check if the class is not a subclass of any other class in the minimal set
        if not any(issubclass(cls, m) for m in minimal):
            minimal.add(cls)

    # Return the minimal set of base classes
    return sorted(minimal, key=classes.index)

