from typing import Dict, List, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(self.messages)

def _validate_labels(labels: Dict[str, Union[str, List[str]]]) -> None:
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Regular expression for valid label keys and values
    label_regex = re.compile(r'^[a-zA-Z0-9_]+$')

    for key, value in labels.items():
        if not isinstance(key, str) or not label_regex.match(key):
            errors.append({str(key): "Label key '{}' does not match the regex {}".format(key, label_regex.pattern)})

        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str) or not label_regex.match(v):
                    errors.append({str(v): "expected string or bytes-like object"})
        elif not isinstance(value, str) or not label_regex.match(value):
            errors.append({str(value): "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not isinstance(app, krake.data.kubernetes.Application):
        raise ValueError("The provided app must be an instance of krake.data.kubernetes.Application")

    default_schemas = {}
    for resource in app.spec.manifest:
        if resource.observer_schema is None:
            # Generate default schema for the resource
            default_schema = {
                "apiVersion": resource.apiVersion,
                "kind": resource.kind,
                "metadata": {
                    "name": resource.metadata.name,
                    "namespace": resource.metadata.namespace
                },
                "spec": {}
            }
            default_schemas[resource.kind] = default_schema

    return default_schemas

