def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Check if manifest_files is a list
    if not isinstance(manifest_files, list):
        raise ValueError("manifest_files must be a list")

    # Check if digests_used is a set
    if not isinstance(digests_used, set):
        raise ValueError("digests_used must be a set")

    # Iterate through each manifest file
    for manifest_file in manifest_files:
        # Check if the manifest file is a dictionary
        if not isinstance(manifest_file, dict):
            raise ValueError("Each manifest file must be a dictionary")

        # Check if the 'digests' key exists in the manifest file
        if 'digests' not in manifest_file:
            raise KeyError("Each manifest file must contain a 'digests' key")

        # Get the digests from the manifest file
        manifest_digests = manifest_file['digests']

        # Check if the digests in the manifest file are present in digests_used
        for digest in manifest_digests:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} from manifest file is not present in digests_used")

        # Check if the digests in digests_used are used in the manifest file
        for digest in digests_used:
            if digest not in manifest_digests:
                raise ValueError(f"Digest {digest} from digests_used is not used in the manifest file")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The prior parameter must be an InventoryValidator object.")

    if self.version != prior.version - 1:
        raise ValueError("The prior version must be exactly one less than the current version.")

    if self.data != prior.data:
        raise ValueError("The data in the prior version must match the current version.")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    if not isinstance(fixity['files'], list):
        raise ValueError("Files in fixity block must be a list")

    for file_info in fixity['files']:
        if not isinstance(file_info, dict):
            raise ValueError("Each file info in fixity block must be a dictionary")

        if 'filename' not in file_info:
            raise ValueError("Each file info in fixity block must contain a 'filename' key")

        if file_info['filename'] not in manifest_files:
            raise ValueError(f"File {file_info['filename']} referenced in fixity block is not in the manifest")

    return True

