import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    for command in commands:
        try:
            if hide_stderr:
                process = subprocess.Popen([command] + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
            else:
                process = subprocess.Popen([command] + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)

            output, _ = process.communicate()

            if verbose:
                print(output.decode())

            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, [command] + args, output.decode())

        except FileNotFoundError:
            raise FileNotFoundError(f"Command '{command}' not found.")
        except Exception as e:
            raise Exception(f"Error running command '{command}': {e}")

