from typing import Set, Tuple, Callable

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    result = []
    current_tag = []

    for char in text:
        if char == '`':
            if in_code_block:
                result.append(''.join(current_tag))
                current_tag = []
            in_code_block = not in_code_block
        elif char == '@' and not in_code_block:
            if current_tag:
                result.append(''.join(current_tag))
                current_tag = []
            current_tag.append(char)
        elif char == ' ' and not in_code_block:
            if current_tag:
                tag = ''.join(current_tag)
                tags.add(tag)
                result.append(tag)
                current_tag = []
            result.append(char)
        else:
            current_tag.append(char)

    if current_tag:
        result.append(''.join(current_tag))

    if replacer:
        result = [replacer(word) if word.startswith('@') else word for word in result]

    return tags, ''.join(result)

