def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not command_name:
        raise ValueError("Command name cannot be empty")

    try:
        command = self.commands[command_name]
    except KeyError:
        raise ValueError(f"Command '{command_name}' not found")

    return command.get_option_specs()

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silenced_args = []
    for arg in args:
        if arg.startswith('_'):
            silenced_args.append(arg)
    return silenced_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """

    required_args = self.REQUIRED_ARGS
    if not required_args:
        return True

    provided_args = set(args.keys())
    missing_args = required_args - provided_args

    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if isinstance(arg, str) and len(arg) > 100:
            raise ValueError(f"Argument '{arg}' exceeds the maximum length of 100 characters.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg, value in args.items():
        if arg in self.choices and value not in self.choices[arg]:
            raise ValueError(f"Invalid value '{value}' for argument '{arg}'. Available choices are: {self.choices[arg]}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError("All arguments must be numbers.")
        if arg < 0:
            raise ValueError("All arguments must be non-negative.")
        if arg > 100:
            raise ValueError("All arguments must be less than or equal to 100.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('control_'):
            control_args[arg.replace('control_', '')] = args[arg]
        elif arg.startswith('nested_'):
            nested_args[arg.replace('nested_', '')] = args[arg]
        elif arg.startswith('custom_'):
            custom_args[arg.replace('custom_', '')] = args[arg]
        else:
            raise ValueError(f"Invalid argument: {arg}")

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        for key, value in extra_vars.items():
            vars_dict[key] = value
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string")
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    for key, value in values_dict.items():
        if key == 'int_arg':
            values_dict[key] = int(value)
        elif key == 'float_arg':
            values_dict[key] = float(value)
        elif key == 'bool_arg':
            values_dict[key] = value.lower() in ['true', '1', 't', 'y', 'yes']

